import { execFileSync } from "child_process";
import Database from "better-sqlite3";
import { DiffFile } from "./adapters/agentAdapter";
import { GraspConfig } from "./types";
import {
  getAllAnsweredConceptTags,
  getConceptTagGlobal,
  getSessionCostUsd,
  getSessionQuestionCount,
  insertEvent,
} from "./store";

/**
 * The single generation path from brief §3.3: one headless `claude -p`
 * call that judges whether a diff is worth a question AND generates the
 * question(s) in the same response. Prompt/response contract design is
 * this phase's own — see DECISIONS.md's "Judge+generate prompt and
 * response contract" entry for the reasoning.
 */

const GENERATION_SOURCE = "headless-claude-p";

/**
 * Ceiling on the `claude -p` subprocess call itself. Deliberately well
 * under the Phase 5 outer Claude Code hook timeout (45s, src/init.ts) —
 * see DECISIONS.md's "Generation subprocess timeout value" entry for the
 * margin reasoning. Hardcoded, not exposed in GraspConfig — see
 * DECISIONS.md's "hardcoded vs configurable" entry for why.
 */
const GENERATION_TIMEOUT_MS = 20_000;

export type MissReason = "cap_reached" | "error" | "timeout";

export interface GenerationOutcome {
  eventId: number;
  missReason: MissReason | null;
  questionType: "concept" | "instance" | "both" | null;
}

export interface GenerationParams {
  sessionId: string;
  repo: string;
  significantFiles: DiffFile[];
  config: GraspConfig;
  /** From `CapturedDiff.diffHash` — see DECISIONS.md's "Checkpoint-based incremental capture" entry. Null when the capturing adapter doesn't compute one. */
  diffHash: string | null;
}

// --- diff_summary (local, deterministic, no model call) -------------------

export function buildDiffSummary(files: DiffFile[]): string {
  const totalInsertions = files.reduce((sum, f) => sum + f.insertions, 0);
  const totalDeletions = files.reduce((sum, f) => sum + f.deletions, 0);
  const fileList = files.map((f) => f.path).join(", ");
  return `${files.length} file${files.length === 1 ? "" : "s"} changed (+${totalInsertions}/-${totalDeletions}): ${fileList}`;
}

// --- prompt construction ----------------------------------------------------

/** Renders significant files as readable "File: ... / @@ hunk @@ / lines" text — the hunk data already IS unified-diff shaped, so no reconstruction of diff --git headers is needed for a model that just needs to read the change. */
function formatDiffForPrompt(files: DiffFile[]): string {
  return files
    .map((file) => {
      const header = `File: ${file.path} (${file.status}, +${file.insertions}/-${file.deletions})`;
      const hunkText = file.hunks
        .map((h) => [h.header, ...h.lines].join("\n"))
        .join("\n");
      return hunkText ? `${header}\n${hunkText}` : header;
    })
    .join("\n\n");
}

function buildJudgePrompt(diffText: string, answeredTags: string[]): string {
  const answeredList = answeredTags.length > 0 ? answeredTags.join(", ") : "none yet";
  return `You are a code-comprehension tutor helping a developer understand a change an AI coding agent just made to their own codebase.

Below is a diff the agent produced. Decide, in this single response:
1. Is this diff worth asking the developer a comprehension question about? Trivial, self-explanatory, or purely mechanical changes are not worth asking about.
2. If worth asking about, pick ONE concept tag naming the general programming concept this diff exercises (e.g. "mutex-vs-channel", "recursion", "sql-injection", "async-await", "binary-search"). Use a short, reusable, kebab-case tag — the same underlying concept in a different file should get the same tag.
3. Check the developer's already-answered concept tags below. If your chosen tag is already in that list, do NOT write a concept question — write the instance question only.
4. If a concept question is warranted (tag not already answered), write one: it tests/teaches the general idea, independent of this specific codebase.
5. Write an instance question that applies the concept directly to this diff. If a concept question was written, the instance question should be answerable BECAUSE of it. If no concept question was written (already known), the instance question should stand alone, referencing the diff directly.

Developer's already-answered concept tags (do not re-teach these): ${answeredList}

Diff:
${diffText}

Respond with ONLY a single JSON object, no other text, no markdown code fence, matching exactly this shape:
{"worthAsking": boolean, "conceptTag": string | null, "questionConcept": string | null, "questionInstance": string | null}

Rules for the JSON:
- If worthAsking is false: conceptTag, questionConcept, and questionInstance must all be null.
- If worthAsking is true: conceptTag must be a non-empty kebab-case string, and questionInstance must be a non-empty string.
- questionConcept must be null if conceptTag is in the already-answered list above; otherwise it must be a non-empty string.`;
}

// --- claude -p invocation and response parsing -----------------------------

interface ClaudeEnvelope {
  /**
   * Null when `total_cost_usd` was missing or not a number in the response
   * — genuinely unknown, never coerced to 0. A response can't be trusted
   * for cap accounting without a real cost figure; see DECISIONS.md's
   * "Missing total_cost_usd treated as unknown, not zero" entry.
   */
  totalCostUsd: number | null;
  resultText: string;
  isError: boolean;
}

/** True when a caught execFileSync error is specifically a timeout kill, not any other failure (spawn error, nonzero exit, ...). Empirically verified (not assumed) against this Node version: a timeout sets `error.code === "ETIMEDOUT"` — `error.killed` is NOT reliably `true` the way Node's own docs might suggest, and `error.signal === "SIGTERM"` alone isn't a safe-enough signal on its own since a process could plausibly exit via SIGTERM for unrelated reasons. See DECISIONS.md's "Timeout detection mechanism" entry. */
export function isTimeoutError(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: unknown }).code === "ETIMEDOUT";
}

/** Shells out to `claude -p`, exactly per brief §3.3's recommended invocation shape. Throws if the process fails, times out, or its stdout isn't valid JSON at all — callers must catch, and can use `isTimeoutError` to distinguish a timeout from any other failure. */
function invokeClaudeJudge(prompt: string): ClaudeEnvelope {
  const stdout = execFileSync(
    "claude",
    ["-p", prompt, "--output-format", "json", "--allowedTools", "", "--max-turns", "1"],
    { encoding: "utf-8", maxBuffer: 1024 * 1024 * 16, timeout: GENERATION_TIMEOUT_MS }
  );
  const envelope = JSON.parse(stdout);
  return {
    totalCostUsd: typeof envelope.total_cost_usd === "number" ? envelope.total_cost_usd : null,
    resultText: typeof envelope.result === "string" ? envelope.result : "",
    isError: Boolean(envelope.is_error),
  };
}

export interface JudgeResponse {
  worthAsking: boolean;
  conceptTag: string | null;
  questionConcept: string | null;
  questionInstance: string | null;
}

/** Strips a ```json ... ``` / ``` ... ``` fence if the model wrapped its JSON in one despite instructions not to. */
function extractJsonBlock(text: string): string {
  const trimmed = text.trim();
  const fenceMatch = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  return fenceMatch ? fenceMatch[1].trim() : trimmed;
}

/** Returns null for anything that doesn't match the contract — malformed JSON, wrong types, or an internally inconsistent shape. Never throws. */
export function parseJudgeResponse(raw: string): JudgeResponse | null {
  let obj: any;
  try {
    obj = JSON.parse(extractJsonBlock(raw));
  } catch {
    return null;
  }
  if (typeof obj !== "object" || obj === null) return null;
  if (typeof obj.worthAsking !== "boolean") return null;

  if (obj.worthAsking === false) {
    if (obj.conceptTag !== null || obj.questionConcept !== null || obj.questionInstance !== null) {
      return null;
    }
    return { worthAsking: false, conceptTag: null, questionConcept: null, questionInstance: null };
  }

  if (typeof obj.conceptTag !== "string" || obj.conceptTag.trim().length === 0) return null;
  if (typeof obj.questionInstance !== "string" || obj.questionInstance.trim().length === 0) return null;
  if (
    obj.questionConcept !== null &&
    (typeof obj.questionConcept !== "string" || obj.questionConcept.trim().length === 0)
  ) {
    return null;
  }

  return {
    worthAsking: true,
    conceptTag: obj.conceptTag.trim(),
    questionConcept: typeof obj.questionConcept === "string" ? obj.questionConcept.trim() : null,
    questionInstance: obj.questionInstance.trim(),
  };
}

// --- main entry point --------------------------------------------------------

function recordMiss(
  db: Database.Database,
  params: GenerationParams,
  diffSummary: string,
  missReason: MissReason,
  costUsd: number | null
): GenerationOutcome {
  const eventId = insertEvent(db, {
    timestamp: new Date().toISOString(),
    repo: params.repo,
    sessionId: params.sessionId,
    diffHash: params.diffHash,
    diffSummary,
    questionConcept: null,
    questionInstance: null,
    questionType: null,
    generationSource: GENERATION_SOURCE,
    missReason,
    answerConcept: null,
    answerInstance: null,
    skipped: false,
    skipReason: null,
    costUsd,
    diffFiles: null,
  });
  return { eventId, missReason, questionType: null };
}

/**
 * Given a diff that already passed Phase 4's mechanical filter, enforces
 * the session-wide cost cap, then (if not capped) runs the single judge+
 * generate call and writes exactly one `events` row — whether or not it
 * produced a question. See DECISIONS.md's prompt/response-contract and
 * malformed-response entries for the design reasoning.
 */
export function runGeneration(db: Database.Database, params: GenerationParams): GenerationOutcome {
  const { sessionId, significantFiles, config } = params;
  const diffSummary = buildDiffSummary(significantFiles);

  const spentSoFar = getSessionCostUsd(db, sessionId);
  if (spentSoFar >= config.costCapUsd) {
    // Cap already met/exceeded — never invoke `claude -p` at all.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const questionsSoFar = getSessionQuestionCount(db, sessionId);
  if (questionsSoFar >= config.questionsPerSessionCap) {
    // Same "never invoke claude -p at all" pattern as the cost cap above,
    // and the same miss_reason — see DECISIONS.md's "Questions-per-session
    // cap: miss-reason reuse" entry for why cap_reached is shared rather
    // than a new value, and for how the two remain distinguishable after
    // the fact from the session's own cost/question totals at the time.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const answeredTags = getAllAnsweredConceptTags(db);
  const diffText = formatDiffForPrompt(significantFiles);
  const prompt = buildJudgePrompt(diffText, answeredTags);

  let envelope: ClaudeEnvelope;
  try {
    envelope = invokeClaudeJudge(prompt);
  } catch (err) {
    // Process never produced a usable envelope at all — no cost figure to
    // record either way (genuinely unknown, not 0). A timeout kill is
    // distinguished from every other spawn/exit failure specifically —
    // see isTimeoutError's own comment for how that's actually detected.
    const missReason: MissReason = isTimeoutError(err) ? "timeout" : "error";
    return recordMiss(db, params, diffSummary, missReason, null);
  }

  if (envelope.isError) {
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (envelope.totalCostUsd === null) {
    // A well-formed, non-error envelope that's missing its own cost figure
    // can't be trusted for cap accounting — recording it as a "free"
    // successful call would let repeated uncosted responses bypass the
    // cost cap entirely (it sums cost_usd, and NULL contributes 0). Treat
    // it as a miss instead — see DECISIONS.md's "Missing total_cost_usd"
    // entry. This intentionally never reaches parseJudgeResponse: even a
    // perfectly well-formed question in this response isn't recorded,
    // since there's no way to know what it actually cost.
    return recordMiss(db, params, diffSummary, "error", null);
  }

  const parsed = parseJudgeResponse(envelope.resultText);
  if (!parsed) {
    // The call succeeded and cost money, but didn't return a usable
    // response — still record that cost so a misbehaving/malformed
    // response can't be used to bypass the cap.
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (!parsed.worthAsking) {
    const eventId = insertEvent(db, {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: null,
      questionInstance: null,
      questionType: null,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      diffFiles: null,
    });
    return { eventId, missReason: null, questionType: null };
  }

  // worthAsking === true. The model was told the already-answered list and
  // instructed to self-censor, but Grasp still enforces the §3.2 rule
  // deterministically against its own DB — the model's own judgment isn't
  // trusted as the sole authority for a correctness guarantee.
  const alreadyAnswered = getConceptTagGlobal(db, parsed.conceptTag as string, true).length > 0;
  const includeConceptQuestion = parsed.questionConcept !== null && !alreadyAnswered;
  const questionType: "instance" | "both" = includeConceptQuestion ? "both" : "instance";

  const eventId = insertEvent(
    db,
    {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: includeConceptQuestion ? parsed.questionConcept : null,
      questionInstance: parsed.questionInstance,
      questionType,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      // Persisted verbatim so `grasp review` renders exactly what the judge
      // model saw — no re-fetch from git, no re-running the Phase 4 filter
      // against a working tree that may have moved on since.
      diffFiles: significantFiles,
    },
    [{ tag: parsed.conceptTag as string, answered: false }]
  );

  return { eventId, missReason: null, questionType };
}
import Database from "better-sqlite3";
import { captureDiffBetweenTrees, emptyCapturedDiff, writeWorktreeTree } from "./gitDiffCapture";
import { AgentAdapter, CapturedDiff } from "./agentAdapter";
import { loadConfig } from "../config";
import { evaluateCapturedDiff } from "../filter";
import { runGeneration } from "../generation";
import {
  completeTurn,
  getCheckpointTree,
  insertCapturedDiff,
  setCheckpointTree,
  upsertTurn,
} from "../store";

/**
 * Fields Claude Code hooks send on stdin, as documented at
 * https://code.claude.com/docs/en/hooks (fetched live — this environment
 * had no way to run an authenticated live Claude Code session to observe
 * a real firing directly; see DECISIONS.md's "hook payload shape" entry
 * for exactly what was and wasn't possible to verify empirically).
 *
 * `session_id`/`cwd`/`hook_event_name` are documented as present on every
 * event and are treated as reliable. `prompt_id` is documented as "absent
 * until first user input" — plausible it's simply always present by the
 * time PreToolUse/PostToolUse/Stop can fire, but this wasn't independently
 * confirmed, so callers must not assume it's always set (see
 * `resolvePromptId` in this file for the defensive fallback).
 */
export interface ClaudeCodeHookPayload {
  session_id: string;
  prompt_id?: string;
  cwd: string;
  hook_event_name: string;
  tool_name?: string;
  tool_input?: unknown;
  tool_use_id?: string;
  tool_output?: unknown;
  tool_response_time_ms?: number;
  last_assistant_message?: string;
  tool_use_count?: number;
  tool_error_count?: number;
  // Forward-compatible: hook payloads may carry fields this type doesn't
  // model yet (transcript_path, permission_mode, effort, agent_id, ...).
  [key: string]: unknown;
}

/**
 * Used when a payload's `prompt_id` is missing. Falling back to a single
 * fixed key (rather than e.g. inventing a random one per call) means an
 * uncertain/absent prompt_id degrades to "one turn per whole session_id" —
 * i.e. exactly the coarser behavior the original (pre-verification) Phase 1
 * assumption described — rather than silently fragmenting into many
 * untracked pseudo-turns.
 */
const FALLBACK_PROMPT_ID = "__no_prompt_id__";

export function resolvePromptId(payload: Pick<ClaudeCodeHookPayload, "prompt_id">): string {
  return payload.prompt_id && payload.prompt_id.length > 0 ? payload.prompt_id : FALLBACK_PROMPT_ID;
}

/**
 * Adapts one Claude Code turn (session_id + prompt_id) to the Phase 2
 * AgentAdapter interface. A turn, not a whole interactive CLI session, is
 * this adapter's unit of work — see DECISIONS.md's "Stop fires per turn,
 * not per session" entry for why that's the correct binding for
 * onSessionComplete's "present before final output" semantics despite the
 * name.
 */
export class ClaudeCodeAdapter implements AgentAdapter {
  readonly supportsHeadlessSelfInvocation = true;
  readonly reportsCost = true;

  constructor(
    private readonly db: Database.Database,
    private readonly sessionId: string,
    private readonly promptId: string,
    private readonly repoPath: string
  ) {}

  /**
   * Checkpoint-based incremental capture: diffs the current working tree
   * against this session+repo's last recorded checkpoint (not always
   * HEAD), so a `PostToolUse` firing only ever surfaces what's genuinely
   * new since the *previous* firing — never the same unchanged diff twice,
   * and never pre-existing uncommitted work that predates this session.
   * See DECISIONS.md's "Checkpoint-based incremental capture" entry for
   * the full design (this fixes a real bug: every firing used to re-diff
   * the whole working tree against HEAD, so two firings with no new work
   * between them generated and paid for the same question twice).
   *
   * `ensureCheckpointSeeded()` is expected to have already run earlier in
   * this same hook invocation (see cli.ts's `runInternalHook`), so a
   * checkpoint should already exist by the time this is called — the
   * defensive re-seed below only matters if that invariant is ever broken.
   */
  checkAndCapture(): CapturedDiff {
    const currentTree = writeWorktreeTree(this.repoPath);
    const previousTree = getCheckpointTree(this.db, this.sessionId, this.repoPath);

    if (previousTree === null || previousTree === currentTree) {
      // Either the very first observation of this session+repo (nothing
      // "new" to report yet — this current state IS the baseline) or
      // nothing has changed since the last capture. Either way: advance
      // the checkpoint to the current state and report no diff.
      setCheckpointTree(this.db, this.sessionId, this.repoPath, currentTree);
      return emptyCapturedDiff(this.repoPath);
    }

    const diffHash = `${previousTree}..${currentTree}`;
    const diff = captureDiffBetweenTrees(this.repoPath, previousTree, currentTree, diffHash);
    setCheckpointTree(this.db, this.sessionId, this.repoPath, currentTree);

    if (diff.files.length > 0) {
      void this.onChangeDetected(diff);
    }
    return diff;
  }

  /**
   * Establishes this session+repo's checkpoint baseline on the FIRST hook
   * firing Grasp observes for it (of any event type — see cli.ts, which
   * calls this unconditionally before dispatching by event name, the same
   * place `ensureTurnStarted` already runs on every firing). Seeding here
   * rather than lazily inside `checkAndCapture` matters: `checkAndCapture`
   * only runs on `PostToolUse`, i.e. *after* a tool call already ran, so
   * seeding there would silently bake that first tool call's own changes
   * into the "already seen" baseline and never surface them. Seeding as
   * early as possible (typically the session's first `PreToolUse`, which
   * fires before any tool runs) is what makes the baseline genuinely
   * pre-agent-work. A cheap read (does a checkpoint already exist?) short-
   * circuits every firing after the first, so this costs real work
   * (building a tree snapshot) exactly once per session+repo.
   */
  ensureCheckpointSeeded(): void {
    if (getCheckpointTree(this.db, this.sessionId, this.repoPath) !== null) return;
    const tree = writeWorktreeTree(this.repoPath);
    setCheckpointTree(this.db, this.sessionId, this.repoPath, tree);
  }

  async onChangeDetected(diff: CapturedDiff): Promise<void> {
    // Persisting to captured_diffs IS part of this phase's job: a hook
    // firing is a background process with no attached terminal, so the
    // SQLite store (not stdout) is the only way this capture is observable
    // at all — unlike Phase 2's debug:capture, which had a human watching
    // a terminal. Every capture is run through Phase 4's mechanical filter
    // before being recorded — see DECISIONS.md's "Filtered-diff recording"
    // entry: a filtered-out diff still gets a row here (filtered=1,
    // filter_reason=<why>), it just never reaches generation.
    const { config } = loadConfig(this.repoPath);
    const verdict = evaluateCapturedDiff(diff, config);

    insertCapturedDiff(this.db, {
      sessionId: this.sessionId,
      promptId: this.promptId,
      repo: diff.repo,
      capturedAt: diff.capturedAt,
      diff,
      filtered: !verdict.passed,
      filterReason: verdict.reason,
    });

    // A passed diff goes straight into Phase 5's judge+generate call. The
    // cost cap is session-wide (see DECISIONS.md's "Resolving Phase 3's
    // flagged consequence" entry), so `runGeneration` sums cost across
    // this session_id, not just this turn, before deciding whether to
    // invoke `claude -p` at all.
    if (verdict.passed) {
      runGeneration(this.db, {
        sessionId: this.sessionId,
        repo: diff.repo,
        significantFiles: verdict.significantFiles,
        config,
        diffHash: diff.diffHash,
      });
    }
  }

  /**
   * Marks this turn complete. Idempotent: if some other invocation already
   * completed this exact (sessionId, promptId) turn, this safely does
   * nothing rather than re-running completion side effects. Flushing a
   * queue and presenting before final output is Phase 7/8 — this phase
   * only proves the "exactly once per turn" boundary is real and
   * detectable.
   */
  async onSessionComplete(): Promise<void> {
    completeTurn(this.db, { sessionId: this.sessionId, promptId: this.promptId });
  }

  /** Ensures the underlying cc_turns row exists, independent of which hook calls it first. */
  ensureTurnStarted(): void {
    upsertTurn(this.db, { sessionId: this.sessionId, promptId: this.promptId, repo: this.repoPath });
  }
}
import * as crypto from "crypto";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import { isGitWorkTree, listUntrackedFiles, resolveBaseRef, runGit } from "../git";
import { AgentAdapter, CapturedDiff, DiffFile, DiffHunk, FileChangeStatus } from "./agentAdapter";

interface NameStatusEntry {
  status: FileChangeStatus;
  path: string;
  oldPath: string | null;
}

interface NumstatEntry {
  insertions: number;
  deletions: number;
}

const STATUS_LETTER_MAP: Record<string, FileChangeStatus> = {
  A: "added",
  M: "modified",
  D: "deleted",
  T: "modified", // file-type change (e.g. symlink <-> regular) — closest fit
};

/** Parses `git diff --name-status -M` output. */
function parseNameStatus(output: string): NameStatusEntry[] {
  return output
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => {
      const fields = line.split("\t");
      const code = fields[0];
      if (code.startsWith("R")) {
        return { status: "renamed" as const, oldPath: fields[1], path: fields[2] };
      }
      const status = STATUS_LETTER_MAP[code[0]] ?? "modified";
      return { status, oldPath: null, path: fields[1] };
    });
}

/** Parses `git diff --numstat -M` output, keyed by the file's new/current path. */
function parseNumstat(output: string): Map<string, NumstatEntry> {
  const map = new Map<string, NumstatEntry>();
  for (const line of output.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const [insRaw, delRaw, pathField] = trimmed.split("\t");
    // Binary files report "-" instead of a count.
    const insertions = insRaw === "-" ? 0 : Number(insRaw);
    const deletions = delRaw === "-" ? 0 : Number(delRaw);
    const newPath = pathField.includes(" => ") ? pathField.split(" => ")[1] : pathField;
    map.set(newPath, { insertions, deletions });
  }
  return map;
}

/** Splits a multi-file `git diff` output into one raw chunk per file. */
function splitIntoFileDiffs(rawDiffText: string): string[] {
  if (!rawDiffText.trim()) return [];
  return rawDiffText
    .split(/(?=^diff --git )/m)
    .map((chunk) => chunk.replace(/\n$/, ""))
    .filter((chunk) => chunk.trim().length > 0);
}

/** Pulls the file path a diff chunk applies to, from its `+++`/`---` header lines. */
function extractPathFromChunk(chunk: string): string | null {
  const lines = chunk.split("\n");
  const plusLine = lines.find((l) => l.startsWith("+++ "));
  const minusLine = lines.find((l) => l.startsWith("--- "));
  const fromHeader = (line: string | undefined): string | null => {
    if (!line || line === "+++ /dev/null" || line === "--- /dev/null") return null;
    // "+++ b/path/to/file" / "--- a/path/to/file" — strip the 6-char prefix.
    return line.slice(6);
  };
  return fromHeader(plusLine) ?? fromHeader(minusLine);
}

/** Extracts `@@ ... @@` hunks (header + body lines) from one file's diff chunk. */
function extractHunks(chunkOrDiffText: string): DiffHunk[] {
  const lines = chunkOrDiffText.split("\n");
  const hunks: DiffHunk[] = [];
  let current: DiffHunk | null = null;
  for (const line of lines) {
    if (line.startsWith("@@")) {
      if (current) hunks.push(current);
      current = { header: line, lines: [] };
    } else if (current) {
      current.lines.push(line);
    }
  }
  if (current) hunks.push(current);
  return hunks;
}

function countInsertions(hunks: DiffHunk[]): number {
  return hunks.reduce(
    (sum, h) => sum + h.lines.filter((l) => l.startsWith("+") && !l.startsWith("+++")).length,
    0
  );
}

/**
 * The same file-level diff parsing logic (name-status for status/rename,
 * numstat for insertion/deletion counts, raw diff text hand-split into
 * hunks by file), shared by `captureGitDiff` (single ref, HEAD-vs-worktree)
 * and `captureDiffBetweenTrees` (two tree-ish args) below — `git diff`'s
 * output format is identical either way, so this is one parser, not two.
 */
function diffFilesBetween(
  repoPath: string,
  fromArg: string,
  toArg: string | null
): { files: DiffFile[]; rawDiffText: string } {
  const refArgs = toArg !== null ? [fromArg, toArg] : [fromArg];
  const nameStatusOut = runGit(repoPath, ["diff", "--no-color", "-M", "--name-status", ...refArgs]).stdout;
  const numstatOut = runGit(repoPath, ["diff", "--no-color", "-M", "--numstat", ...refArgs]).stdout;
  const rawDiffText = runGit(repoPath, ["diff", "--no-color", "-M", ...refArgs]).stdout.replace(/\n$/, "");

  const statuses = parseNameStatus(nameStatusOut);
  const stats = parseNumstat(numstatOut);
  const chunks = splitIntoFileDiffs(rawDiffText);

  const files: DiffFile[] = statuses.map((entry) => {
    const stat = stats.get(entry.path) ?? { insertions: 0, deletions: 0 };
    const chunk = chunks.find((c) => {
      const chunkPath = extractPathFromChunk(c);
      return chunkPath === entry.path || (entry.oldPath !== null && chunkPath === entry.oldPath);
    });
    return {
      path: entry.path,
      oldPath: entry.oldPath,
      status: entry.status,
      insertions: stat.insertions,
      deletions: stat.deletions,
      hunks: chunk ? extractHunks(chunk) : [],
    };
  });

  return { files, rawDiffText };
}

/**
 * Captures the working-tree diff for a repo: everything changed since the
 * last commit (staged + unstaged, via `git diff HEAD`) plus untracked files
 * not excluded by .gitignore. Read-only — never touches the index.
 *
 * See DECISIONS.md's "Git-diff capture: comparison mechanism" entry for why
 * HEAD (not the index, not a stored snapshot) is the comparison base for
 * this function specifically — it's the right base for a manual, one-shot
 * "show me everything uncommitted right now" inspection command
 * (`debug:capture`/`GitDiffAdapter`). `ClaudeCodeAdapter`'s hook-driven
 * capture uses `captureDiffBetweenTrees` instead — see that function's own
 * doc comment for why HEAD is the wrong base there.
 */
export function captureGitDiff(repoPath: string): CapturedDiff {
  const absoluteRepoPath = path.resolve(repoPath);

  if (!isGitWorkTree(absoluteRepoPath)) {
    throw new Error(`Grasp: ${absoluteRepoPath} is not inside a git working tree.`);
  }

  const baseRef = resolveBaseRef(absoluteRepoPath);
  const { files: trackedFiles, rawDiffText: rawTrackedDiff } = diffFilesBetween(
    absoluteRepoPath,
    baseRef,
    null
  );

  const untrackedRawChunks: string[] = [];
  const untrackedFiles: DiffFile[] = listUntrackedFiles(absoluteRepoPath).map((filePath) => {
    // git diff --no-index exits 1 when it finds differences (expected, not an error).
    const diffText = runGit(
      absoluteRepoPath,
      ["diff", "--no-color", "--no-index", "--", "/dev/null", filePath],
      [0, 1]
    ).stdout;
    const trimmedDiffText = diffText.replace(/\n$/, "");
    untrackedRawChunks.push(trimmedDiffText);
    const hunks = extractHunks(trimmedDiffText);
    return {
      path: filePath,
      oldPath: null,
      status: "added",
      insertions: countInsertions(hunks),
      deletions: 0,
      hunks,
    };
  });

  const files = [...trackedFiles, ...untrackedFiles];
  const rawDiffText = [rawTrackedDiff.replace(/\n$/, ""), ...untrackedRawChunks]
    .filter((chunk) => chunk.length > 0)
    .join("\n");

  return {
    repo: absoluteRepoPath,
    capturedAt: new Date().toISOString(),
    files,
    rawDiffText,
    // No checkpoint concept on this path (see the module doc comment above
    // writeWorktreeTree/captureDiffBetweenTrees) — always HEAD-vs-worktree,
    // so there are no two endpoints to name a hash after.
    diffHash: null,
  };
}

// --- Checkpoint-based incremental capture (ClaudeCodeAdapter only) --------
//
// `captureGitDiff` above always diffs HEAD-vs-worktree — correct for a
// manual, one-shot inspection command (`debug:capture`/`GitDiffAdapter`,
// "show me everything uncommitted right now"), but wrong for a hook-driven
// capture that fires after every tool call: re-diffing the whole working
// tree every time re-surfaces the same accumulated changes on every firing
// with no new work in between, and can attribute uncommitted changes that
// predate the agent's turn entirely to the agent. See DECISIONS.md's
// "Checkpoint-based incremental capture" entry for the full design
// rationale and the alternatives that were considered and rejected.
//
// The mechanism: snapshot the exact current working tree (tracked +
// untracked, respecting .gitignore) as a real git tree object, using a
// throwaway index file (via `GIT_INDEX_FILE`) that's never wired up as the
// repo's real index — so this never stages anything a real `git status`/
// `git commit` would see. Two such snapshots taken at different times can
// then be diffed against EACH OTHER with the exact same `git diff`
// invocations already used above (tree-ish vs tree-ish behaves identically
// to ref vs ref for --name-status/--numstat/raw output), which is what
// makes an untracked file correctly show as "modified" rather than
// "deleted" between two checkpoints — a plain `git diff <tree>` against the
// live worktree does NOT do this correctly for untracked paths, since it's
// actually a tree-vs-INDEX comparison under the hood and the real index
// never has untracked entries at all (verified empirically before choosing
// this design — a tree-vs-worktree "single ref" diff for a tree containing
// an untracked file's prior snapshot showed it as *deleted*, not modified,
// even when the file was present and unchanged on disk).

/**
 * Builds a git tree object representing the exact current state of the
 * working tree (every tracked file's current content, plus every untracked
 * file not excluded by .gitignore) and returns its SHA. Never touches the
 * repo's real index — `GIT_INDEX_FILE` points `read-tree`/`add`/`write-tree`
 * at a throwaway file for the duration of this call, deleted afterward.
 */
export function writeWorktreeTree(repoPath: string): string {
  const absoluteRepoPath = path.resolve(repoPath);
  const seedRef = resolveBaseRef(absoluteRepoPath);
  const scratchIndexPath = path.join(
    os.tmpdir(),
    `grasp-idx-${process.pid}-${Date.now()}-${crypto.randomBytes(4).toString("hex")}`
  );
  try {
    const env = { GIT_INDEX_FILE: scratchIndexPath };
    runGit(absoluteRepoPath, ["read-tree", seedRef], [0], env);
    runGit(absoluteRepoPath, ["add", "-A"], [0], env);
    const { stdout } = runGit(absoluteRepoPath, ["write-tree"], [0], env);
    return stdout.trim();
  } finally {
    fs.rmSync(scratchIndexPath, { force: true });
  }
}

/**
 * Diffs two `writeWorktreeTree` snapshots against each other (via the same
 * `diffFilesBetween` parser defined above `captureGitDiff`) — the actual
 * incremental-capture primitive `ClaudeCodeAdapter.checkAndCapture` uses.
 * `diffHash` is the caller's job to compute (conventionally
 * `${fromTree}..${toTree}`, git's own range-diff notation — a real,
 * reproducible identifier a developer could hand back to `git diff`
 * themselves) since this function only knows the two tree SHAs, not what
 * convention the caller wants recorded.
 */
export function captureDiffBetweenTrees(
  repoPath: string,
  fromTree: string,
  toTree: string,
  diffHash: string
): CapturedDiff {
  const absoluteRepoPath = path.resolve(repoPath);
  const { files, rawDiffText } = diffFilesBetween(absoluteRepoPath, fromTree, toTree);
  return {
    repo: absoluteRepoPath,
    capturedAt: new Date().toISOString(),
    files,
    rawDiffText,
    diffHash,
  };
}

/** A capture with no changes — used both when a checkpoint is freshly seeded (nothing "new" yet by definition) and when two consecutive checkpoints are identical (nothing changed since the last capture). */
export function emptyCapturedDiff(repoPath: string): CapturedDiff {
  return {
    repo: path.resolve(repoPath),
    capturedAt: new Date().toISOString(),
    files: [],
    rawDiffText: "",
    diffHash: null,
  };
}

/**
 * Adapter-shaped wrapper around `captureGitDiff`. Agent-agnostic: works
 * against any git repo regardless of which coding agent (if any) produced
 * the changes, which is why it reports no headless generation capability
 * and no cost self-reporting of its own — those are properties of a
 * specific coding agent's CLI, not of git itself.
 */
export class GitDiffAdapter implements AgentAdapter {
  readonly supportsHeadlessSelfInvocation = false;
  readonly reportsCost = false;

  constructor(private readonly repoPath: string) {}

  /**
   * Captures the current diff and, if non-empty, notifies via
   * onChangeDetected. This is the shape a future poll loop would call on
   * an interval; nothing calls it on a timer yet in Phase 2. Returns the
   * diff (including empty results) so callers like the debug CLI can
   * inspect it directly without depending on the notification path.
   */
  checkForChanges(): CapturedDiff {
    const diff = captureGitDiff(this.repoPath);
    if (diff.files.length > 0) {
      void this.onChangeDetected(diff);
    }
    return diff;
  }

  async onChangeDetected(_diff: CapturedDiff): Promise<void> {
    // Phase 4's mechanical filter (src/filter.ts) exists and is wired into
    // ClaudeCodeAdapter, which already has a DB handle and a session/turn
    // to record against. GitDiffAdapter has neither (it's a manual/poll
    // capture with no hook-driven session concept), so there's nowhere
    // meaningful to persist a filter verdict yet — see DECISIONS.md's
    // "Filter wiring scope" entry. Forwarding a passed diff into real
    // question generation is still Phase 5 regardless.
  }

  async onSessionComplete(): Promise<void> {
    // Flushing the queue and presenting before final output is Phase 7/8.
  }
}

import { CapturedDiff, DiffFile, DiffHunk } from "./adapters/agentAdapter";
import { BASELINE_IGNORE_PATTERNS } from "./ignoreBaseline";
import { GraspConfig } from "./types";

/**
 * Purely mechanical pre-filtering (brief §5.2's mechanical half only — no
 * semantic "is this interesting" judgment lives here; see DECISIONS.md's
 * "Flagged-pattern filtering" entry from Phase 4's planning and the
 * formatting-only/filtered-diff-recording entries added in this phase).
 */

export type FilterReason =
  | "baseline_ignore"
  | "user_ignore_pattern"
  | "formatting_only"
  | "below_min_threshold"
  | "above_max_threshold";

export type FileExclusionReason = "baseline_ignore" | "user_ignore_pattern" | "formatting_only";

export interface ExcludedFile {
  path: string;
  reason: FileExclusionReason;
}

export interface FilterResult {
  passed: boolean;
  reason: FilterReason | null;
  /**
   * Files that survived exclusion — what a future Phase 5 should actually
   * operate on. Empty whenever `passed` is false.
   */
  significantFiles: DiffFile[];
  excludedFiles: ExcludedFile[];
  totalChangedLines: number;
  maxSingleFileChangedLines: number;
}

// --- Ignore-pattern matching -------------------------------------------

/**
 * A pattern ending in "/" matches a directory anywhere in the path (e.g.
 * "node_modules/" matches "packages/a/node_modules/x.js"). Anything else
 * matches by exact basename or exact full relative path (e.g.
 * "package-lock.json" matches both "package-lock.json" and
 * "packages/a/package-lock.json"). No glob syntax — see DECISIONS.md's
 * "Ignore-pattern matching syntax" entry for why.
 */
export function matchesIgnorePattern(filePath: string, pattern: string): boolean {
  const normalizedPath = filePath.replace(/\\/g, "/").replace(/^\.\//, "");
  if (pattern.endsWith("/")) {
    const dirName = pattern.slice(0, -1);
    const dirSegments = normalizedPath.split("/").slice(0, -1);
    return dirSegments.includes(dirName);
  }
  const basename = normalizedPath.split("/").pop() ?? normalizedPath;
  return basename === pattern || normalizedPath === pattern;
}

function classifyIgnoreExclusion(filePath: string, config: GraspConfig): FileExclusionReason | null {
  if (BASELINE_IGNORE_PATTERNS.some((p) => matchesIgnorePattern(filePath, p))) {
    return "baseline_ignore";
  }
  if (config.ignorePatterns.some((p) => matchesIgnorePattern(filePath, p))) {
    return "user_ignore_pattern";
  }
  return null;
}

// --- Formatting-only detection ------------------------------------------

/**
 * Collapses insignificant whitespace: trims the line and collapses any run
 * of internal whitespace to a single space. Reindentation, trailing
 * whitespace, and tabs-vs-spaces all normalize identically; anything that
 * changes actual tokens does not.
 */
function normalizeLine(line: string): string {
  return line.trim().replace(/\s+/g, " ");
}

/** A hunk's removed lines (with their `-` prefix stripped), normalized, in order. */
function normalizedRemovedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("-") && !l.startsWith("---"))
    .map((l) => normalizeLine(l.slice(1)));
}

/** A hunk's added lines (with their `+` prefix stripped), normalized, in order. */
function normalizedAddedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("+") && !l.startsWith("+++"))
    .map((l) => normalizeLine(l.slice(1)));
}

function arraysEqual(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

/**
 * A hunk is formatting-only if its normalized removed-line sequence exactly
 * equals its normalized added-line sequence (same content, same order —
 * order matters so a real reordering of statements is never mistaken for
 * formatting). A hunk with no removed/added lines at all (shouldn't happen
 * in practice, but) counts as formatting-only vacuously.
 */
function isHunkFormattingOnly(hunk: DiffHunk): boolean {
  return arraysEqual(normalizedRemovedLines(hunk), normalizedAddedLines(hunk));
}

/** A file is formatting-only only if every one of its hunks is. */
export function isFileFormattingOnly(file: DiffFile): boolean {
  if (file.hunks.length === 0) return false;
  return file.hunks.every(isHunkFormattingOnly);
}

// --- Main filter ----------------------------------------------------------

function pickEmptyReason(excludedFiles: ExcludedFile[]): FilterReason {
  // Priority: a user-specified pattern is the most intentional signal, then
  // the baseline list, then formatting-only (the most inferred of the
  // three). Only matters when a multi-file diff is emptied by a mix of
  // reasons — none of Phase 4's own verification scenarios hit this, but
  // the order needs to be defined rather than left to iteration order.
  if (excludedFiles.some((f) => f.reason === "user_ignore_pattern")) return "user_ignore_pattern";
  if (excludedFiles.some((f) => f.reason === "baseline_ignore")) return "baseline_ignore";
  return "formatting_only";
}

/**
 * Applies Phase 4's mechanical filter to a captured diff. Two file-level
 * exclusion passes run first (ignore patterns, then formatting-only),
 * producing a "significant files" set; size thresholds are then evaluated
 * against ONLY that remaining set — so a file excluded by either pass
 * doesn't count toward or against the size thresholds. See DECISIONS.md's
 * "Diff-size thresholds: per-file exclusion, not whole-diff" entry.
 */
export function evaluateCapturedDiff(diff: CapturedDiff, config: GraspConfig): FilterResult {
  const excludedFiles: ExcludedFile[] = [];
  const significantFiles: DiffFile[] = [];

  for (const file of diff.files) {
    const ignoreReason = classifyIgnoreExclusion(file.path, config);
    if (ignoreReason) {
      excludedFiles.push({ path: file.path, reason: ignoreReason });
      continue;
    }
    if (isFileFormattingOnly(file)) {
      excludedFiles.push({ path: file.path, reason: "formatting_only" });
      continue;
    }
    significantFiles.push(file);
  }

  if (significantFiles.length === 0) {
    return {
      passed: false,
      reason: pickEmptyReason(excludedFiles),
      significantFiles: [],
      excludedFiles,
      totalChangedLines: 0,
      maxSingleFileChangedLines: 0,
    };
  }

  const fileSizes = significantFiles.map((f) => f.insertions + f.deletions);
  const totalChangedLines = fileSizes.reduce((sum, n) => sum + n, 0);
  const maxSingleFileChangedLines = Math.max(...fileSizes);

  const { minChangedLines, maxTotalChangedLines, maxSingleFileChangedLines: maxSingleFileCap } =
    config.diffThresholds;

  if (totalChangedLines > maxTotalChangedLines || maxSingleFileChangedLines > maxSingleFileCap) {
    return {
      passed: false,
      reason: "above_max_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  const anyFileClearsMinimum = fileSizes.some((size) => size >= minChangedLines);
  if (!anyFileClearsMinimum) {
    return {
      passed: false,
      reason: "below_min_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  return {
    passed: true,
    reason: null,
    significantFiles,
    excludedFiles,
    totalChangedLines,
    maxSingleFileChangedLines,
  };
}
import * as fs from "fs";
import * as path from "path";
import * as readline from "readline";

const HOOK_COMMAND = "grasp internal:hook";
// PostToolUse now runs Phase 5's synchronous `claude -p` judge+generate
// call inline, which the original Phase 3 default (15s) didn't anticipate
// and could plausibly cut off before a real headless call completes. 45s
// isn't a Phase 6 "defensive timeout on the subprocess call itself" (that's
// still unbuilt — this is just the outer Claude Code hook timeout that
// already existed, sized to fit what now runs inside it).
const HOOK_TIMEOUT_SECONDS = 45;
const HOOK_EVENTS = ["PreToolUse", "PostToolUse", "Stop"] as const;
type HookEventName = (typeof HOOK_EVENTS)[number];

interface HookEntry {
  matcher?: string;
  hooks: Array<{ type: string; command: string; timeout?: number }>;
}

interface HooksSection {
  [eventName: string]: HookEntry[] | undefined;
}

interface ClaudeSettings {
  hooks?: HooksSection;
  [key: string]: unknown;
}

function desiredEntry(matcher: "*" | null): HookEntry {
  const entry: HookEntry = {
    hooks: [{ type: "command", command: HOOK_COMMAND, timeout: HOOK_TIMEOUT_SECONDS }],
  };
  if (matcher !== null) entry.matcher = matcher;
  return entry;
}

// PreToolUse/PostToolUse need a matcher (every tool); Stop isn't tool-scoped,
// matching the shape Claude Code's own docs example uses for non-tool events.
const DESIRED: Record<HookEventName, HookEntry> = {
  PreToolUse: desiredEntry("*"),
  PostToolUse: desiredEntry("*"),
  Stop: desiredEntry(null),
};

/** Index of the entry containing a Grasp hook command, or -1 if this event has no Grasp entry at all yet. */
function findGraspEntryIndex(entries: HookEntry[] | undefined): number {
  return (entries ?? []).findIndex((entry) => entry.hooks?.some((h) => h.command === HOOK_COMMAND));
}

/**
 * Structural (not JSON.stringify-string) comparison — an existing entry's
 * keys could be in any order depending on how/when it was originally
 * written, so string equality would false-positive "stale" on nothing more
 * than key ordering.
 */
function entriesEqual(a: HookEntry, b: HookEntry): boolean {
  if (a.matcher !== b.matcher) return false;
  if (a.hooks.length !== b.hooks.length) return false;
  return a.hooks.every((h, i) => h.type === b.hooks[i].type && h.command === b.hooks[i].command && h.timeout === b.hooks[i].timeout);
}

function askConfirmation(question: string): Promise<boolean> {
  return new Promise((resolve) => {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    rl.question(question, (answer) => {
      rl.close();
      resolve(/^y(es)?$/i.test(answer.trim()));
    });
  });
}

/**
 * Installs Grasp's Claude Code hooks into `<repoRoot>/.claude/settings.local.json`
 * — project-scoped and local-only (gitignored by Claude Code convention), not
 * `~/.claude/settings.json` (all projects) or the committed `.claude/settings.json`.
 * See DECISIONS.md's "Hook config location" entry for why: per-repo opt-in
 * matches how `grasp init` is meant to be run (once per repo the user wants
 * monitored), and a committed file would silently enable Grasp for every
 * teammate who clones the repo without their own confirmation.
 */
export async function runInit(repoRoot: string): Promise<void> {
  const settingsPath = path.join(repoRoot, ".claude", "settings.local.json");

  let existing: ClaudeSettings = {};
  if (fs.existsSync(settingsPath)) {
    const raw = fs.readFileSync(settingsPath, "utf-8");
    try {
      existing = JSON.parse(raw);
    } catch (err) {
      // Consistent with the Phase 1 config-loading policy: fail loudly,
      // never silently overwrite a file we can't parse.
      throw new Error(
        `Grasp: ${settingsPath} exists but is not valid JSON (${(err as Error).message}). ` +
          `Fix or remove it manually — Grasp will not overwrite a file it can't parse.`
      );
    }
  }

  const hooks: HooksSection = { ...(existing.hooks ?? {}) };

  // Every event falls into exactly one bucket: no Grasp entry yet (missing),
  // a Grasp entry present but not what a fresh install would write today
  // (stale — e.g. an old timeout value from before the Phase 5 15s->45s
  // bump), or already correct. See DECISIONS.md's "grasp init stale-hook
  // detection" entry — this used to only check bucket 1, so anyone who ran
  // `grasp init` against an older version of Grasp kept whatever was
  // written back then forever, with no way short of manually editing the
  // file to notice or fix it.
  const missing: HookEventName[] = [];
  const stale: HookEventName[] = [];
  for (const eventName of HOOK_EVENTS) {
    const idx = findGraspEntryIndex(hooks[eventName]);
    if (idx === -1) {
      missing.push(eventName);
    } else if (!entriesEqual((hooks[eventName] as HookEntry[])[idx], DESIRED[eventName])) {
      stale.push(eventName);
    }
  }

  if (missing.length === 0 && stale.length === 0) {
    process.stdout.write(`Grasp hooks already installed and up to date in ${settingsPath} — nothing to do.\n`);
    return;
  }

  // Snapshot the "before" shape of stale entries for the confirmation
  // message before mutating the working copy.
  const staleBefore = new Map<HookEventName, HookEntry>();
  for (const eventName of stale) {
    const idx = findGraspEntryIndex(hooks[eventName]);
    staleBefore.set(eventName, (hooks[eventName] as HookEntry[])[idx]);
  }

  for (const eventName of missing) {
    hooks[eventName] = [...(hooks[eventName] ?? []), DESIRED[eventName]];
  }
  for (const eventName of stale) {
    const idx = findGraspEntryIndex(hooks[eventName]);
    const updated = [...(hooks[eventName] as HookEntry[])];
    updated[idx] = DESIRED[eventName];
    hooks[eventName] = updated;
  }

  const updatedSettings: ClaudeSettings = { ...existing, hooks };

  const messageLines: string[] = [];
  if (missing.length > 0) {
    messageLines.push(
      `Grasp will add the following hook(s) to ${settingsPath}:`,
      "",
      JSON.stringify({ hooks: Object.fromEntries(missing.map((e) => [e, DESIRED[e]])) }, null, 2),
      ""
    );
  }
  if (stale.length > 0) {
    messageLines.push(
      `Grasp will UPDATE the following existing hook(s) in ${settingsPath} — they were installed`,
      "by an older version of `grasp init` and are out of date (e.g. a stale timeout value):",
      ""
    );
    for (const eventName of stale) {
      messageLines.push(
        `  ${eventName}:`,
        `    before: ${JSON.stringify(staleBefore.get(eventName))}`,
        `    after:  ${JSON.stringify(DESIRED[eventName])}`,
        ""
      );
    }
  }
  messageLines.push(
    `This registers \`${HOOK_COMMAND}\` for ${[...missing, ...stale].join(", ")} so Grasp can observe file`,
    "changes and turn completions during your Claude Code sessions in this repo. It never",
    "modifies a tool call's own input or output. In the default gate mode (soft), it never",
    "blocks anything either — it only reads and records, and nudges you toward",
    "`grasp review` when a question is waiting. If you opt into gateMode: \"hard\" in your",
    "config, it will deny the next tool call while a question from this session is still",
    "unanswered, until you answer or explicitly skip it via `grasp review`.",
    "",
    "This draws from your existing Claude plan/usage when Grasp later generates",
    "questions (subscription rate-limit headroom, or small API cost if API-billed).",
    ""
  );

  process.stdout.write(messageLines.join("\n"));

  const confirmed = await askConfirmation("Apply these changes? [y/N] ");
  if (!confirmed) {
    process.stdout.write("Aborted — no changes made.\n");
    return;
  }

  fs.mkdirSync(path.dirname(settingsPath), { recursive: true });
  fs.writeFileSync(settingsPath, JSON.stringify(updatedSettings, null, 2) + "\n", "utf-8");
  process.stdout.write(`Wrote ${settingsPath}\n`);
  process.stdout.write(
    "Note: settings.local.json is meant to stay on your machine only — if this repo doesn't\n" +
      "already gitignore it, consider adding .claude/settings.local.json to .gitignore.\n"
  );
}
import * as React from "react";
import { loadInk } from "./inkLoader";
import { createReviewApp, ReviewQueueItem } from "./reviewApp";
import { EventRecord } from "./types";
import { getPendingQuestions, markEventAnswered, markEventSkipped, openStore } from "./store";

/**
 * Groups pending events into batches by `session_id` — same session's
 * questions stay adjacent — while preserving each session-group's overall
 * chronological position (the earliest-timestamped question in a session
 * decides where that whole group falls relative to other sessions). Within
 * a group, order is oldest-first, inherited directly from `events` already
 * being timestamp-ASC (see `getPendingQuestions`) — no re-sort needed
 * there. Events with no `session_id` (e.g. `debug:seed` rows) each form
 * their own singleton group rather than being merged together, since they
 * have no real session relationship to one another. See DECISIONS.md's
 * "grasp review batch ordering/grouping" entry.
 */
function groupForBatchPresentation(events: EventRecord[]): ReviewQueueItem[] {
  const order: string[] = [];
  const groups = new Map<string, EventRecord[]>();
  for (const event of events) {
    const key = event.sessionId ?? `__no_session_${event.id}`;
    if (!groups.has(key)) {
      groups.set(key, []);
      order.push(key);
    }
    groups.get(key)!.push(event);
  }

  const items: ReviewQueueItem[] = [];
  order.forEach((key, groupIndex) => {
    const groupEvents = groups.get(key)!;
    groupEvents.forEach((event, positionInGroup) => {
      items.push({
        event,
        sessionPosition: positionInGroup + 1,
        sessionSize: groupEvents.length,
        batchIndex: groupIndex + 1,
        batchCount: order.length,
      });
    });
  });
  return items;
}

/**
 * `grasp review` — the one place in the codebase with genuine terminal
 * access (see DECISIONS.md's TTY-access finding). Queries pending
 * questions globally across all repos (see the "grasp review query scope"
 * entry), groups/orders them into a coherent batch (Phase 8), renders them
 * one at a time via ink, and writes answers/skips straight back to the
 * store.
 */
export async function runReview(): Promise<void> {
  if (!process.stdin.isTTY) {
    process.stderr.write(
      "grasp review needs an interactive terminal (stdin is not a TTY) — run it directly in a terminal, not piped or scripted.\n"
    );
    process.exitCode = 1;
    return;
  }

  const db = openStore();
  const pending = getPendingQuestions(db);

  if (pending.length === 0) {
    process.stdout.write("No pending questions — you're caught up.\n");
    db.close();
    return;
  }

  const items = groupForBatchPresentation(pending);

  const { ink, TextInput } = await loadInk();
  const App = createReviewApp({ ink, TextInput });

  const instance = ink.render(
    React.createElement(App, {
      items,
      onAnswer: (eventId: number, answers: { answerConcept: string | null; answerInstance: string | null }) => {
        markEventAnswered(db, eventId, answers);
      },
      onSkip: (eventId: number, skipReason: string | null) => {
        markEventSkipped(db, eventId, skipReason);
      },
    })
  );

  await instance.waitUntilExit();
  db.close();
}
import * as React from "react";
import type { InkModules } from "./inkLoader";
import type { DiffFile } from "./adapters/agentAdapter";
import type { EventRecord } from "./types";

const { useState, useEffect, useCallback } = React;

/**
 * `grasp review`'s TUI, built as a factory over the dynamically-loaded ink
 * module (see inkLoader.ts) rather than importing `ink`'s components as
 * module-level values — JSX only needs `Box`/`Text`/etc. to be identifiers
